  if (!Array.isArray(start) || start.length < 2 || start.length > 100000) return 'start needs 2 to 10^5 values.';
  if (start.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each start value is an integer from 0 to 10^9.';
  if (!Number.isInteger(d) || d < 0 || d > 1000000000) return 'd is an integer from 0 to 10^9.';
