function maxPossibleScore(start, d) {
  start.sort((a, b) => a - b);
  const n = start.length;

  function canSpace(gap) {
    let last = start[0];
    for (let i = 1; i < n; i++) {
      const pick = Math.max(start[i], last + gap);
      if (pick > start[i] + d) {
        return false;
      }
      last = pick;
    }
    return true;
  }

  let low = 0;
  let high = Math.floor((start[n - 1] + d - start[0]) / (n - 1));
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    if (canSpace(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

