function maxPossibleScore(start, d) {
  // Try every left-to-right order of the picks. In a fixed order, consecutive picks can all be g apart
  // exactly when each later range can still sit (steps * g) above each earlier one:
  // start[earlier] + steps * g <= start[later] + d. The best g for the order is the smallest such bound.
  const n = start.length;
  const order = [];
  const used = new Array(n).fill(false);
  let best = 0;
  function extend() {
    if (order.length === n) {
      let score = Infinity;
      for (let a = 0; a < n; a++)
        for (let b = a + 1; b < n; b++)
          score = Math.min(score, Math.floor((start[order[b]] + d - start[order[a]]) / (b - a)));
      best = Math.max(best, score);
      return;
    }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      order.push(i);
      extend();
      order.pop();
      used[i] = false;
    }
  }
  extend();
  return best;
}

