function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 5);
  const shape = rand();
  let top;
  if (large) top = shape < 0.4 ? 1000000000 : shape < 0.7 ? 1000000 : 3000;
  else top = shape < 0.2 ? 1000000000 : 3 + Math.floor(rand() * 15);
  const start = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  const pickD = rand();
  let d;
  if (large) d = pickD < 0.4 ? Math.floor(rand() * 1000000001) : Math.floor(rand() * 5001);
  else d = pickD < 0.15 ? Math.floor(rand() * 1000000001) : pickD < 0.3 ? 0 : Math.floor(rand() * 12);
  return [start, d];
}
